95	export const claudeEditTools: readonly string[] = [ClaudeToolNames.Edit, ClaudeToolNames.MultiEdit, ClaudeToolNames.Write, ClaudeToolNames.NotebookEdit];
96	
97	export function getAffectedUrisForEditTool(toolName: string, toolInput: unknown): URI[] {
98		switch (toolName) {
99			case ClaudeToolNames.Edit:
100			case ClaudeToolNames.MultiEdit:
101				return [URI.file((toolInput as FileEditInput).file_path)];
102			case ClaudeToolNames.Write:
103				return [URI.file((toolInput as FileWriteInput).file_path)];
104			case ClaudeToolNames.NotebookEdit:
105				return [URI.file((toolInput as NotebookEditInput).notebook_path)];
106			default:
107				return [];
108		}
109	}
