function isSubagentParentToolName(name: string): boolean {
	return name === ClaudeToolNames.Task || name === ClaudeToolNames.Agent;
}

/**
 * Builds a map from a parent tool_use_id to the subagent sessions it spawned.
 * Subagents without a `parentToolUseId` are excluded entirely — they cannot be
 * linked to a parent tool invocation and must not contribute any tool parts.
 */
function buildSubagentsByParentToolUseId(subagents: readonly ISubagentSession[]): Map<string, ISubagentSession[]> {
	const map = new Map<string, ISubagentSession[]>();
	for (const subagent of subagents) {
		if (!subagent.parentToolUseId) {
			continue;
		}
		const existing = map.get(subagent.parentToolUseId);
		if (existing) {
			existing.push(subagent);
		} else {
			map.set(subagent.parentToolUseId, [subagent]);
		}
	}
	return map;
}

/**
 * Collects the ids of all Agent/Task tool_use blocks in the session. Only these
 * ids are valid parents for subagent nesting, so a subagent whose
 * `parentToolUseId` points at any other tool is not injected.
 */
function collectParentToolUseIds(messages: readonly StoredMessage[]): Set<string> {
	const ids = new Set<string>();
	for (const message of messages) {
		if (message.type === 'assistant' && message.message.role === 'assistant') {
			for (const block of (message.message as AssistantMessageContent).content) {
				if (isToolUseBlock(block) && isSubagentParentToolName(block.name)) {
					ids.add(block.id);
				}
			}
		}
	}
	return ids;
}

